contracts/manager/TTMAccountManager.sol.content:
// SPDX-License-Identifier: LGPL-3.0-or-later
//
// Travel Token Messenger Account Manager

pragma solidity 0.8.24;

// UUPS Proxy
import { Initializable } from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import { ERC1967Proxy } from "@openzeppelin/contracts/proxy/ERC1967/ERC1967Proxy.sol";
import { UUPSUpgradeable } from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

// Access
import { PausableUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import { AccessControlEnumerableUpgradeable } from "@openzeppelin/contracts-upgradeable/access/extensions/AccessControlEnumerableUpgradeable.sol";
import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";

// ABI of the TTMAccount implementation contract
import { ITTMAccount } from "../account/ITTMAccount.sol";

// Utils
import { Address } from "@openzeppelin/contracts/utils/Address.sol";
import { EnumerableSet } from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";

// Service Registry
import { ServiceRegistry } from "../partner/ServiceRegistry.sol";

/**
 * @title Travel Token Messenger Account Manager
 * @notice This contract manages the creation of the Travel Token Messenger accounts by
 * deploying {ERC1967Proxy} proxies that point to the{TTMAccount} implementation
 * address.
 *
 * Create TTM Account: Users who want to create an account should call
 * `createTTMAccount(address admin, address upgrader)` function with addresses of
 * the accounts admin and upgrader roles.
 *
 * When the manager contract is paused, account creation is stopped.
 *
 * Service Registry: {TTMAccountManager} also acts as a registry for the services
 * that {TTMAccount} contracts add as a supported or wanted service. Registry
 * works by hashing (keccak256) the service name (string) and creating a mapping
 * as keccak256(serviceName) => serviceName. And provides functions that
 * {TTMAccount} function uses to register services. The {TTMAccount} only keeps
 * the hashes (byte32) of the registered services.
 */
contract TTMAccountManager is
    Initializable,
    PausableUpgradeable,
    AccessControlEnumerableUpgradeable,
    UUPSUpgradeable,
    ReentrancyGuardUpgradeable,
    ServiceRegistry
{
    using Address for address payable;
    using EnumerableSet for EnumerableSet.AddressSet;

    /**
     * @notice Pauser role can pause the contract. Currently this only affects the
     * creation of TTM Accounts. When paused, account creation is stopped.
     */
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    /**
     * @notice Upgrader role can upgrade the contract to a new implementation.
     */
    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");

    /**
     * @notice Versioner role can set new {TTMAccount} implementation address. When a
     * new implementation address is set, it is used for the new {TTMAccount}
     * creations.
     *
     * The old {TTMAccount} contracts are not affected by this. Owners of those
     * should do the upgrade manually by calling the `upgradeToAndCall(address)`
     * function on the account.
     */
    bytes32 public constant VERSIONER_ROLE = keccak256("VERSIONER_ROLE");

    /**
     * @notice Service registry admin role can add and remove services to the service
     * registry mapping. Implemented by {ServiceRegistry} contract.
     */
    bytes32 public constant SERVICE_REGISTRY_ADMIN_ROLE = keccak256("SERVICE_REGISTRY_ADMIN_ROLE");

    /***************************************************
     *                   STORAGE                       *
     ***************************************************/

    /// @custom:storage-location erc7201:traveltoken.messenger.storage.TTMAccountManager
    struct TTMAccountManagerStorage {
        /**
         * @dev TTM Account implementation address to be used by the TTMAccount contract to restrict
         * the implementation address for the UUPS proxies.
         */
        address _latestAccountImplementation;
        /**
         * @dev BookingToken address.
         */
        address _bookingToken;
        /**
         * @dev Every TTM Account created by this manager. This is the single source of
         * truth for account identity. `_createTTMAccount` is the only writer and there
         * is no external mutator, so this set cannot diverge from reality.
         */
        EnumerableSet.AddressSet _ttmAccounts;
        /**
         * @dev Creator of each TTM Account, keyed by the account address.
         */
        mapping(address account => address creator) _ttmAccountCreator;
    }

    // keccak256(abi.encode(uint256(keccak256("traveltoken.messenger.storage.TTMAccountManager")) - 1)) & ~bytes32(uint256(0xff));
    bytes32 private constant TTMAccountManagerStorageLocation =
        0x82fd17ead72ea2acbf4028d3b6fb6ced2f61d2d2be6f5996ded313320918c700;

    function _getTTMAccountManagerStorage() private pure returns (TTMAccountManagerStorage storage $) {
        assembly {
            $.slot := TTMAccountManagerStorageLocation
        }
    }

    /***************************************************
     *                    EVENTS                       *
     ***************************************************/

    /**
     * @notice Emitted when a TTM Account is created.
     *
     * @dev Carries creator and admin so indexers need no follow-up call per account.
     *
     * @param account The address of the newly created TTM Account
     * @param creator The address that called {createTTMAccount}
     * @param admin The admin address granted on the new account
     */
    event TTMAccountCreated(address indexed account, address indexed creator, address indexed admin);

    /**
     * @notice TTM Account implementation address updated event.
     * @param oldImplementation The old implementation address
     * @param newImplementation The new implementation address
     */
    event TTMAccountImplementationUpdated(address indexed oldImplementation, address indexed newImplementation);

    /**
     * @notice Booking token address updated event.
     * @param oldBookingToken The old booking token address
     * @param newBookingToken The new booking token address
     */
    event BookingTokenAddressUpdated(address indexed oldBookingToken, address indexed newBookingToken);

    /***************************************************
     *                    ERRORS                       *
     ***************************************************/

    /**
     * @notice The implementation of the TTMAccount is invalid.
     * @param implementation The implementation address of the TTMAccount
     */
    error TTMAccountInvalidImplementation(address implementation);

    /**
     * @notice The admin address is invalid.
     * @param admin The admin address
     */
    error TTMAccountInvalidAdmin(address admin);

    /**
     * @notice Invalid booking token address.
     * @param bookingToken The booking token address
     */
    error InvalidBookingTokenAddress(address bookingToken);

    /**
     * @notice A required address parameter was the zero address.
     */
    error ZeroAddress();

    /***************************************************
     *                    FUNCS                        *
     ***************************************************/

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        address defaultAdmin, // can grant roles
        address pauser, // can pause the manager
        address upgrader, // can upgrade the manager (this contract)
        address versioner // can set TTMAccount implementation address
    ) public initializer {
        if (defaultAdmin == address(0) || pauser == address(0) || upgrader == address(0) || versioner == address(0)) {
            revert ZeroAddress();
        }

        __Pausable_init();
        __AccessControl_init();
        __UUPSUpgradeable_init();
        __ReentrancyGuard_init();
        __ServiceRegistry_init();

        _grantRole(DEFAULT_ADMIN_ROLE, defaultAdmin);
        _grantRole(PAUSER_ROLE, pauser);
        _grantRole(UPGRADER_ROLE, upgrader);
        _grantRole(VERSIONER_ROLE, versioner);
    }

    /**
     * @notice Pauses the TTMAccountManager contract. Currently this only affects the
     * creation of TTMAccount. When paused, account creation is stopped.
     */
    function pause() public onlyRole(PAUSER_ROLE) {
        _pause();
    }

    /**
     * @notice Unpauses the TTMAccountManager contract.
     */
    function unpause() public onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    /**
     * @notice Authorization for the TTMAccountManager contract upgrade.
     */
    function _authorizeUpgrade(address newImplementation) internal override onlyRole(UPGRADER_ROLE) {}

    /***************************************************
     *                    ACCOUNT                      *
     ***************************************************/

    /**
     * @notice Creates a new TTMAccount.
     *
     * This function is currently permissionless: any address may create an
     * account. See docs/decisions/2026-07-21-contract-design-decisions.md
     * (Decision 1) -- gating must be resolved before Base mainnet.
     *
     * @dev Emits a {TTMAccountCreated} event.
     */
    function createTTMAccount(
        address admin,
        address upgrader
    ) external payable nonReentrant whenNotPaused returns (address) {
        return _createTTMAccount(admin, upgrader);
    }

    /**
     * @notice Private function to create a `TTMAccount`.
     */
    function _createTTMAccount(address admin, address upgrader) private returns (address) {
        // Checks
        if (admin == address(0)) {
            revert TTMAccountInvalidAdmin(admin);
        }

        address latestAccountImplementation = getAccountImplementation();
        if (latestAccountImplementation.code.length == 0) {
            revert TTMAccountInvalidImplementation(latestAccountImplementation);
        }

        address bookingToken = getBookingTokenAddress();
        if (bookingToken.code.length == 0) {
            revert InvalidBookingTokenAddress(bookingToken);
        }

        // Create TTMAccount Proxy and set the implementation address
        ERC1967Proxy ttmAccountProxy = new ERC1967Proxy(latestAccountImplementation, "");

        // Initialize the TTMAccount
        ITTMAccount(address(ttmAccountProxy)).initialize(address(this), bookingToken, admin, upgrader);

        // Record the account and its creator. This is the only writer.
        TTMAccountManagerStorage storage $ = _getTTMAccountManagerStorage();
        $._ttmAccounts.add(address(ttmAccountProxy));
        $._ttmAccountCreator[address(ttmAccountProxy)] = msg.sender;

        // [ETH] Send the msg.value to the TTMAccount
        payable(ttmAccountProxy).sendValue(msg.value);

        emit TTMAccountCreated(address(ttmAccountProxy), msg.sender, admin);

        return address(ttmAccountProxy);
    }

    /**
     * @notice Returns the given account's creator, or the zero address if the
     * address is not a TTM Account.
     *
     * @param account The account address
     */
    function getTTMAccountCreator(address account) public view returns (address) {
        return _getTTMAccountManagerStorage()._ttmAccountCreator[account];
    }

    /**
     * @notice Returns whether the given address is a TTM Account created by this manager.
     *
     * @param account The address to check
     */
    function isTTMAccount(address account) public view returns (bool) {
        return _getTTMAccountManagerStorage()._ttmAccounts.contains(account);
    }

    /**
     * @notice Returns the number of TTM Accounts created by this manager.
     */
    function getTTMAccountCount() public view returns (uint256) {
        return _getTTMAccountManagerStorage()._ttmAccounts.length();
    }

    /**
     * @notice Returns every TTM Account created by this manager.
     *
     * @dev Unbounded. Prefer {getTTMAccountsSlice} against a public RPC once the
     * ecosystem grows past a few hundred accounts.
     */
    function getTTMAccounts() public view returns (address[] memory) {
        return _getTTMAccountManagerStorage()._ttmAccounts.values();
    }

    /**
     * @notice Returns a bounded window of TTM Accounts, for callers that cannot
     * afford an unbounded read.
     *
     * Returns an empty array if `offset` is at or past the end. The window is
     * clamped to the end of the set, so a `limit` larger than the remainder is
     * not an error.
     *
     * @param offset Index to start at
     * @param limit Maximum number of accounts to return
     */
    function getTTMAccountsSlice(uint256 offset, uint256 limit) public view returns (address[] memory accounts) {
        EnumerableSet.AddressSet storage ttmAccounts = _getTTMAccountManagerStorage()._ttmAccounts;
        uint256 total = ttmAccounts.length();
        if (offset >= total) {
            return new address[](0);
        }

        // Clamp by subtraction, not by computing `offset + limit`: under checked
        // arithmetic that sum reverts for a large `limit`, which would contradict
        // the "an oversized limit is not an error" contract above. `offset < total`
        // here, so `total - offset` cannot underflow.
        uint256 remaining = total - offset;
        if (limit > remaining) {
            limit = remaining;
        }

        accounts = new address[](limit);
        for (uint256 i = 0; i < limit; i++) {
            accounts[i] = ttmAccounts.at(offset + i);
        }
    }

    /***************************************************
     *             ACCOUNT IMPLEMENTATION              *
     ***************************************************/

    /**
     * @notice Returns the TTMAccount implementation address.
     */
    function getAccountImplementation() public view returns (address) {
        TTMAccountManagerStorage storage $ = _getTTMAccountManagerStorage();
        return $._latestAccountImplementation;
    }

    /**
     * @notice Set a new TTMAccount implementation address.
     * @param newImplementation The new implementation address
     */
    function setAccountImplementation(address newImplementation) public onlyRole(VERSIONER_ROLE) {
        if (newImplementation.code.length == 0) {
            revert TTMAccountInvalidImplementation(newImplementation);
        }

        address oldImplementation = getAccountImplementation();
        _setAccountImplementation(newImplementation);
        emit TTMAccountImplementationUpdated(oldImplementation, newImplementation);
    }

    function _setAccountImplementation(address newImplementation) internal {
        TTMAccountManagerStorage storage $ = _getTTMAccountManagerStorage();
        $._latestAccountImplementation = newImplementation;
    }

    /***************************************************
     *                  BOOKING TOKEN                  *
     ***************************************************/

    /**
     * @notice Returns the booking token address.
     */
    function getBookingTokenAddress() public view returns (address) {
        TTMAccountManagerStorage storage $ = _getTTMAccountManagerStorage();
        return $._bookingToken;
    }

    /**
     * @notice Sets booking token address.
     */
    function setBookingTokenAddress(address token) public onlyRole(VERSIONER_ROLE) {
        if (token.code.length == 0) {
            revert InvalidBookingTokenAddress(token);
        }

        address oldToken = getBookingTokenAddress();
        _setBookingTokenAddress(token);
        emit BookingTokenAddressUpdated(oldToken, token);
    }

    function _setBookingTokenAddress(address token) internal {
        TTMAccountManagerStorage storage $ = _getTTMAccountManagerStorage();
        $._bookingToken = token;
    }

    /***************************************************
     *               SERVICE REGISTRY                  *
     ***************************************************/

    /**
     * @notice Registers a given service name. TTM Accounts can only register services
     * if they are also registered in the service registry on the manager contract.
     *
     * @param serviceName Name of the service
     */
    function registerService(string memory serviceName) public onlyRole(SERVICE_REGISTRY_ADMIN_ROLE) {
        _registerServiceName(serviceName);
    }

    /**
     * @notice Unregisters a given service name. TTM Accounts will not be able to register
     * the service anymore.
     *
     * @param serviceName Name of the service
     */
    function unregisterService(string memory serviceName) public onlyRole(SERVICE_REGISTRY_ADMIN_ROLE) {
        _unregisterServiceName(serviceName);
    }
}

contracts/partner/PartnerConfiguration.s.content:
// SPDX-License-Identifier: LGPL-3.0-or-later
//
// Travel Token Messenger Partner Configuration

pragma solidity 0.8.24;

import { Initializable } from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import { EnumerableSet } from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";

/**
 * @title PartnerConfiguration
 * @notice Partner Configuration is used by the {TTMAccount} contract to register
 * supported and wanted services by the partner.
 */
abstract contract PartnerConfiguration is Initializable {
    using EnumerableSet for EnumerableSet.Bytes32Set;
    using EnumerableSet for EnumerableSet.AddressSet;

    /***************************************************
     *                   STORAGE                       *
     ***************************************************/

    /**
     * @notice Struct for storing supported service details for suppliers
     */
    struct Service {
        /**
         * @dev  If set to true, this means the service is restricted to pre-agreement
         * with the partner. (Not a rack rate)
         */
        bool _restrictedRate;
        string[] _capabilities;
    }

    struct PaymentInfo {
        EnumerableSet.AddressSet _supportedTokens; // Supported on-chain token for payment
    }

    /// @custom:storage-location erc7201:traveltoken.messenger.storage.PartnerConfiguration
    struct PartnerConfigurationStorage {
        // Set of supported service hashes
        EnumerableSet.Bytes32Set _servicesHashSet;
        // Mapping of service hashes to the service details
        mapping(bytes32 _serviceHash => Service _service) _supportedServices;
        // Payment
        PaymentInfo _paymentInfo;
        // Public keys, keep a enumerable list of public key addresses
        EnumerableSet.AddressSet _publicKeyAddressesSet;
        // Public keys for encrypting private data for Booking Token
        mapping(address publicKeyAddress => bytes publicKey) _publicKeys;
        // Services that this distributors want to buy
        EnumerableSet.Bytes32Set _wantedServicesHashSet;
    }

    // keccak256(abi.encode(uint256(keccak256("traveltoken.messenger.storage.PartnerConfiguration")) - 1)) & ~bytes32(uint256(0xff));
    bytes32 private constant PartnerConfigurationStorageLocation =
        0x39fc6f3ebcc11656ef8cd451e9e1f6a26855304f0f1787c5b86c527a1e2d8600;

    function _getPartnerConfigurationStorage() private pure returns (PartnerConfigurationStorage storage $) {
        assembly {
            $.slot := PartnerConfigurationStorageLocation
        }
    }

    /***************************************************
     *                    ERRORS                       *
     ***************************************************/

    error ServiceAlreadyExists(bytes32 serviceHash);
    error ServiceDoesNotExist(bytes32 serviceHash);

    error WantedServiceAlreadyExists(bytes32 serviceHash);
    error WantedServiceDoesNotExist(bytes32 serviceHash);

    error PaymentTokenAlreadyExists(address token);
    error PaymentTokenDoesNotExist(address token);

    error PublicKeyAlreadyExists(address pubKeyAddress);
    error PublicKeyDoesNotExist(address pubKeyAddress);

    error CapabilityDoesNotExist(bytes32 serviceHash, string capability);

    /***************************************************
     *                    EVENTS                       *
     ***************************************************/

    event PaymentTokenAdded(address indexed token);
    event PaymentTokenRemoved(address indexed token);

    event PublicKeyAdded(address indexed pubKeyAddress);
    event PublicKeyRemoved(address indexed pubKeyAddress);

    /***************************************************
     *                 INITIALIZATION                  *
     ***************************************************/

    function __PartnerConfiguration_init() internal onlyInitializing {}

    function __PartnerConfiguration_init_unchained() internal onlyInitializing {}

    /***************************************************
     *                   SERVICE                       *
     ***************************************************/

    /**
     * @notice Adds a supported Service object for a given hash.
     *
     * @param serviceHash Hash of the service
     * @param capabilities Capabilities for the service
     * @param restrictedRate If the service is restricted to pre-agreement
     */
    function _addService(bytes32 serviceHash, string[] memory capabilities, bool restrictedRate) internal virtual {
        PartnerConfigurationStorage storage $ = _getPartnerConfigurationStorage();

        // Try to add the service to the services hash set
        bool added = $._servicesHashSet.add(serviceHash);
        if (!added) {
            revert ServiceAlreadyExists(serviceHash);
        }
        $._supportedServices[serviceHash] = Service({ _capabilities: capabilities, _restrictedRate: restrictedRate });
    }

    /**
     * @notice Removes a supported Service object for a given hash.
     *
     * @param serviceHash Hash of the service
     */
    function _removeService(bytes32 serviceHash) internal virtual {
        PartnerConfigurationStorage storage $ = _getPartnerConfigurationStorage();

        // Try to remove the service
        bool removed = $._servicesHashSet.remove(serviceHash);
        if (!removed) {
            revert ServiceDoesNotExist(serviceHash);
        }

        delete $._supportedServices[serviceHash];
    }

    /**
     * @notice Sets the Service restricted rate for a given hash.
     *
     * @param serviceHash Hash of the service
     * @param restrictedRate Restricted rate
     */
    function _setServiceRestrictedRate(bytes32 serviceHash, bool restrictedRate) internal virtual {
        PartnerConfigurationStorage storage $ = _getPartnerConfigurationStorage();

        // Check if the service exists
        _checkServiceExists(serviceHash, $);

        $._supportedServices[serviceHash]._restrictedRate = restrictedRate;
    }

    /**
     * @notice Sets the Service capabilities for a given hash.
     *
     * @param serviceHash Hash of the service
     * @param capabilities Capabilities
     */
    function _setServiceCapabilities(bytes32 serviceHash, string[] memory capabilities) internal virtual {
        PartnerConfigurationStorage storage $ = _getPartnerConfigurationStorage();

        // Check if the service exists
        _checkServiceExists(serviceHash, $);

        $._supportedServices[serviceHash]._capabilities = capabilities;
    }

    /**
     * @notice Adds a capability to the service.
     *
     * @param serviceHash Hash of the service
     * @param capability Capability
     */
    function _addServiceCapability(bytes32 serviceHash, string memory capability) internal virtual {
        PartnerConfigurationStorage storage $ = _getPartnerConfigurationStorage();

        // Check if the service exists
        _checkServiceExists(serviceHash, $);

        $._supportedServices[serviceHash]._capabilities.push(capability);
    }

    /**
     * @notice Removes a capability from the service.
     *
     * @param serviceHash Hash of the service
     * @param capability Capability
     */
    function _removeServiceCapability(bytes32 serviceHash, string memory capability) internal virtual {
        PartnerConfigurationStorage storage $ = _getPartnerConfigurationStorage();

        // Check if the service exists
        _checkServiceExists(serviceHash, $);

        string[] storage capabilities = $._supportedServices[serviceHash]._capabilities;
        uint256 length = capabilities.length;
        for (uint256 i = 0; i < length; i++) {
            if (keccak256(abi.encodePacked(capabilities[i])) == keccak256(abi.encodePacked(capability))) {
                capabilities[i] = capabilities[length - 1];
                capabilities.pop();
                return;
            }
        }
        revert CapabilityDoesNotExist(serviceHash, capability);
    }

    /**
     * @notice Returns all supported service hashes.
     */
    function getAllServiceHashes() public view returns (bytes32[] memory serviceHashes) {
        PartnerConfigurationStorage storage $ = _getPartnerConfigurationStorage();
        return $._servicesHashSet.values();
    }

    /**
     * @notice Returns the Service object for a given hash. Service object contains fee and capabilities.
     *
     * `serviceHash` is keccak256 hash of the pkg + service name as:
     *
     * ```text
     *            ┌────────────── pkg ─────────────┐ ┌───── service name ─────┐
     * keccak256("ttm.services.accommodation.v1alpha.AccommodationSearchService")
     * ```
     * @dev These services are coming from the Travel Token Messenger Protocol's protobuf
     * definitions.
     *
     * @param serviceHash Hash of the service
     */
    function getService(bytes32 serviceHash) public view virtual returns (Service memory service) {
        PartnerConfigurationStorage storage $ = _getPartnerConfigurationStorage();

        // Check if the service exists
        _checkServiceExists(serviceHash, $);

        return $._supportedServices[serviceHash];
    }

    /**
     * @notice Checks if the service is supported.
     *
     * @param serviceHash Hash of the service
     */
    function _isServiceSupported(bytes32 serviceHash) internal view returns (bool) {
        PartnerConfigurationStorage storage $ = _getPartnerConfigurationStorage();
        return $._servicesHashSet.contains(serviceHash);
    }

    /**
     * @notice Returns the restricted rate for a given service hash.
     *
     * @param serviceHash Hash of the service
     */
    function getServiceRestrictedRate(bytes32 serviceHash) public view virtual returns (bool restrictedRate) {
        PartnerConfigurationStorage storage $ = _getPartnerConfigurationStorage();

        // Check if the service exists
        _checkServiceExists(serviceHash, $);

        return $._supportedServices[serviceHash]._restrictedRate;
    }

    /**
     * @notice Returns the capabilities for a given service hash.
     *
     * @param serviceHash Hash of the service
     */
    function getServiceCapabilities(bytes32 serviceHash) public view virtual returns (string[] memory capabilities) {
        PartnerConfigurationStorage storage $ = _getPartnerConfigurationStorage();

        // Check if the service exists
        _checkServiceExists(serviceHash, $);

        return $._supportedServices[serviceHash]._capabilities;
    }

    /**
     * @notice Checks if the service exists.
     *
     * @param serviceHash Hash of the service
     */
    function _checkServiceExists(bytes32 serviceHash, PartnerConfigurationStorage storage $) private view {
        // Check if the service exists
        if (!$._servicesHashSet.contains(serviceHash)) {
            revert ServiceDoesNotExist(serviceHash);
        }
    }

    /***************************************************
     *               WANTED SERVICES                   *
     ***************************************************/

    /**
     * @notice Adds a wanted service hash to the wanted services set.
     *
     * Reverts if the service already exists.
     *
     * @param serviceHash Hash of the service
     */
    function _addWantedService(bytes32 serviceHash) internal virtual {
        PartnerConfigurationStorage storage $ = _getPartnerConfigurationStorage();

        bool added = $._wantedServicesHashSet.add(serviceHash);

        if (!added) {
            revert WantedServiceAlreadyExists(serviceHash);
        }
    }

    /**
     * @notice Removes a wanted service hash from the wanted services set.
     *
     * Reverts if the service does not exist.
     *
     * @param serviceHash Hash of the service
     */
    function _removeWantedService(bytes32 serviceHash) internal virtual {
        PartnerConfigurationStorage storage $ = _getPartnerConfigurationStorage();

        bool removed = $._wantedServicesHashSet.remove(serviceHash);

        if (!removed) {
            revert WantedServiceDoesNotExist(serviceHash);
        }
    }

    /**
     * @notice Returns all wanted service hashes.
     *
     * @return serviceHashes Wanted service hashes
     */
    function getWantedServiceHashes() public view virtual returns (bytes32[] memory serviceHashes) {
        PartnerConfigurationStorage storage $ = _getPartnerConfigurationStorage();
        return $._wantedServicesHashSet.values();
    }

    /***************************************************
     *                   PAYMENT                       *
     ***************************************************/

    // PAYMENT INFO: SUPPORTED TOKENS

    /**
     * @notice Adds a supported payment token.
     *
     * @param _token Payment token address to be added
     */
    function _addSupportedToken(address _token) internal virtual {
        PartnerConfigurationStorage storage $ = _getPartnerConfigurationStorage();
        bool added = $._paymentInfo._supportedTokens.add(_token);

        if (!added) {
            revert PaymentTokenAlreadyExists(_token);
        }

        emit PaymentTokenAdded(_token);
    }

    /**
     * @notice Removes a supported payment token.
     *
     * @param _token Payment token address to be removed
     */
    function _removeSupportedToken(address _token) internal virtual {
        PartnerConfigurationStorage storage $ = _getPartnerConfigurationStorage();
        bool removed = $._paymentInfo._supportedTokens.remove(_token);

        if (!removed) {
            revert PaymentTokenDoesNotExist(_token);
        }

        emit PaymentTokenRemoved(_token);
    }

    /**
     * @notice Returns supported token addresses.
     *
     * @return tokens Supported token addresses
     */
    function getSupportedTokens() public view virtual returns (address[] memory tokens) {
        PartnerConfigurationStorage storage $ = _getPartnerConfigurationStorage();
        return $._paymentInfo._supportedTokens.values();
    }

    /**
     * @notice Returns whether a payment token is declared as supported.
     *
     * The two sentinel values are legitimate members of this set:
     * `address(0)` means native currency and `address(1)` means off-chain
     * payment, matching how `BookingToken` encodes payment mode.
     *
     * @param _token Payment token address, or a sentinel
     * @return supported Whether the token is declared
     */
    function isSupportedToken(address _token) public view virtual returns (bool supported) {
        PartnerConfigurationStorage storage $ = _getPartnerConfigurationStorage();
        return $._paymentInfo._supportedTokens.contains(_token);
    }

    /***************************************************
     *                 PUBLIC KEYS                     *
     ***************************************************/

    /**
     * @notice Adds public key with an address. Reverts if the public key already
     * exists.
     *
     * Beware: This functions does not check if the public key is actually for the
     * given address.
     */
    function _addPublicKey(address pubKeyAddress, bytes memory publicKeyData) internal virtual {
        PartnerConfigurationStorage storage $ = _getPartnerConfigurationStorage();

        bool added = $._publicKeyAddressesSet.add(pubKeyAddress);

        if (!added) {
            revert PublicKeyAlreadyExists(pubKeyAddress);
        }

        $._publicKeys[pubKeyAddress] = publicKeyData;

        emit PublicKeyAdded(pubKeyAddress);
    }

    /**
     * @notice Removes the public key for a given address
     *
     * Reverts if the public key does not exist
     */
    function _removePublicKey(address pubKeyAddress) internal virtual {
        PartnerConfigurationStorage storage $ = _getPartnerConfigurationStorage();

        bool removed = $._publicKeyAddressesSet.remove(pubKeyAddress);

        if (!removed) {
            revert PublicKeyDoesNotExist(pubKeyAddress);
        }

        delete $._publicKeys[pubKeyAddress];
        emit PublicKeyRemoved(pubKeyAddress);
    }

    /**
     * @notice Returns the addresses of all public keys. These can then be used to
     * retrieve the public keys the `getPublicKey(address)` function.
     */
    function getPublicKeysAddresses() public view virtual returns (address[] memory pubKeyAddresses) {
        PartnerConfigurationStorage storage $ = _getPartnerConfigurationStorage();
        return $._publicKeyAddressesSet.values();
    }

    /**
     * @notice Returns the public key for a given address.
     *
     * Reverts if the public key does not exist
     *
     * @param pubKeyAddress Address of the public key
     */
    function getPublicKey(address pubKeyAddress) public view virtual returns (bytes memory data) {
        PartnerConfigurationStorage storage $ = _getPartnerConfigurationStorage();

        if (!$._publicKeyAddressesSet.contains(pubKeyAddress)) {
            revert PublicKeyDoesNotExist(pubKeyAddress);
        }

        return $._publicKeys[pubKeyAddress];
    }
}

contracts/partner/ServiceRegistry.sol.content:
// SPDX-License-Identifier: LGPL-3.0-or-later
//
// Travel Token Messenger Service Registry for Partner Configuration

pragma solidity 0.8.24;

import { Initializable } from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import { EnumerableSet } from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";

/**
 * @title ServiceRegistry
 * @notice Service registry is used by the {TTMAccountManager} contract to register
 * services by hashing (keccak256) the service name (string) and creating a mapping
 * as keccak256(serviceName) => serviceName.
 */
abstract contract ServiceRegistry is Initializable {
    /***************************************************
     *                   STORAGE                       *
     ***************************************************/

    using EnumerableSet for EnumerableSet.Bytes32Set;

    /// @custom:storage-location erc7201:traveltoken.messenger.storage.ServiceRegistry
    struct ServiceRegistryStorage {
        EnumerableSet.Bytes32Set _servicesHashSet; // set of REGISTERED service hashes
        mapping(bytes32 serviceHash => string serviceName) _serviceNameByHash; // Mapping to resolve hash to name
        mapping(string serviceName => bytes32 serviceHash) _hashByServiceName; // Mapping to resolve name to hash
    }

    // keccak256(abi.encode(uint256(keccak256("traveltoken.messenger.storage.ServiceRegistry")) - 1)) & ~bytes32(uint256(0xff));
    bytes32 private constant ServiceRegistryStorageLocation =
        0xfbffdc0c9e6d9fb390c0fd8b4c21854410f48ddb93440f164b71177338057e00;

    function _getServiceRegistryStorage() private pure returns (ServiceRegistryStorage storage $) {
        assembly {
            $.slot := ServiceRegistryStorageLocation
        }
    }

    /***************************************************
     *                    EVENTS                       *
     ***************************************************/

    /**
     * @notice Emitted when a service is registered.
     *
     * @dev The hash is indexed for filtering; the name travels in the data section so
     * consumers can build a complete name-to-hash map from logs alone, with no
     * `eth_call`. This is the authoritative publication of that mapping - `TTMAccount`
     * emits hashes only.
     */
    event ServiceRegistered(bytes32 indexed serviceHash, string serviceName);

    /**
     * @notice Emitted when a service is unregistered.
     *
     * @dev Existing accounts can still resolve a deprecated name, so this is the only
     * signal that a service was retired. See {_unregisterServiceName}.
     */
    event ServiceUnregistered(bytes32 indexed serviceHash, string serviceName);

    /***************************************************
     *                    ERRORS                       *
     ***************************************************/

    error ServiceAlreadyRegistered(string serviceName);
    error ServiceNotRegistered();

    /***************************************************
     *                 INITIALIZATION                  *
     ***************************************************/

    function __ServiceRegistry_init() internal onlyInitializing {}

    function __ServiceRegistry_init_unchained() internal onlyInitializing {}

    /***************************************************
     *                    FUNCS                        *
     ***************************************************/

    /**
     * @notice Adds a new service by its name. This function calculates the hash of the
     * service name and adds it to the registry
     *
     * {serviceName} is the pkg + service name as:
     *
     * ```text
     *  ┌────────────── pkg ─────────────┐ ┌───── service name ─────┐
     * "ttm.services.accommodation.v1alpha.AccommodationSearchService"
     * ```
     * @dev These services are coming from the Travel Token Messenger Protocol's protobuf
     * definitions.
     *
     * @param serviceName Name of the service
     */
    function _registerServiceName(string memory serviceName) internal virtual {
        bytes32 serviceHash = keccak256(abi.encodePacked(serviceName));

        ServiceRegistryStorage storage $ = _getServiceRegistryStorage();

        // Try to add the hash to the service set
        bool added = $._servicesHashSet.add(serviceHash);

        if (!added) {
            revert ServiceAlreadyRegistered(serviceName);
        }

        $._serviceNameByHash[serviceHash] = serviceName;
        $._hashByServiceName[serviceName] = serviceHash;

        emit ServiceRegistered(serviceHash, serviceName);
    }

    /**
     * @notice Removes a service by its name. This function calculates the hash of the
     * service name and removes it from the registry.
     *
     * @param serviceName Name of the service
     */
    function _unregisterServiceName(string memory serviceName) internal virtual {
        bytes32 serviceHash = keccak256(abi.encodePacked(serviceName));

        ServiceRegistryStorage storage $ = _getServiceRegistryStorage();

        // Try to remove the hash to the service set
        bool removed = $._servicesHashSet.remove(serviceHash);

        if (!removed) {
            revert ServiceNotRegistered();
        }

        emit ServiceUnregistered(serviceHash, serviceName);
    }

    /**
     * @notice Returns the name of a registered service by its hash.
     *
     * @param serviceHash Hash of the service
     */
    function getRegisteredServiceNameByHash(bytes32 serviceHash) public view returns (string memory serviceName) {
        ServiceRegistryStorage storage $ = _getServiceRegistryStorage();

        // Check if the service is registered
        if (!$._servicesHashSet.contains(serviceHash)) {
            revert ServiceNotRegistered();
        }
        return $._serviceNameByHash[serviceHash];
    }

    /**
     * @notice Returns the name of a service by its hash. Even if the service is unregistered at the moment.
     *
     * @param serviceHash Hash of the service
     */
    function getServiceNameByHash(bytes32 serviceHash) public view returns (string memory serviceName) {
        ServiceRegistryStorage storage $ = _getServiceRegistryStorage();
        return $._serviceNameByHash[serviceHash];
    }

    /**
     * @notice Returns the hash of a service by its name.
     *
     * @param serviceName Name of the service
     */
    function getRegisteredServiceHashByName(string memory serviceName) public view returns (bytes32 serviceHash) {
        ServiceRegistryStorage storage $ = _getServiceRegistryStorage();

        // Check if the service is registered
        if (!$._servicesHashSet.contains(keccak256(abi.encodePacked(serviceName)))) {
            revert ServiceNotRegistered();
        }

        return $._hashByServiceName[serviceName];
    }

    /**
     * @notice Returns the hash of a service by its name. Even if the service is unregistered at the moment.
     *
     * @param serviceName Name of the service
     */
    function getServiceHashByName(string memory serviceName) public view returns (bytes32 serviceHash) {
        ServiceRegistryStorage storage $ = _getServiceRegistryStorage();
        return $._hashByServiceName[serviceName];
    }

    /**
     * @notice Returns all registered service **hashes**.
     *
     * @return services All registered service hashes
     */
    function getAllRegisteredServiceHashes() public view returns (bytes32[] memory services) {
        ServiceRegistryStorage storage $ = _getServiceRegistryStorage();
        return $._servicesHashSet.values();
    }

    /**
     * @notice Returns all registered service **names**.
     *
     * @return services All registered service names
     */
    function getAllRegisteredServiceNames() public view returns (string[] memory services) {
        ServiceRegistryStorage storage $ = _getServiceRegistryStorage();

        // Get all hashes and create a list with predefined length
        bytes32[] memory serviceHashes = $._servicesHashSet.values();
        string[] memory serviceNames = new string[](serviceHashes.length);

        // Get all names for the hashes
        for (uint256 i = 0; i < serviceHashes.length; i++) {
            serviceNames[i] = $._serviceNameByHash[serviceHashes[i]];
        }

        return serviceNames;
    }
}

